import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // P_ij is the element of C that this thread will compute
    float Pvalue = 0;

    // Loop over the tiles of A and B that are needed to compute C_tile
    // Each block computes a BLOCK_SIZE x BLOCK_SIZE section of C
    // C_tile = A_tile * B_tile
    // A_tile is BLOCK_SIZE x N, B_tile is N x BLOCK_SIZE
    // We need to iterate over N / BLOCK_SIZE tiles
    for (int m = 0; m < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; ++m) {
        // Shared memory for A_tile and B_tile
        __shared__ float sA[BLOCK_SIZE][BLOCK_SIZE];
        __shared__ float sB[BLOCK_SIZE][BLOCK_SIZE];

        // Load A_tile from global memory to shared memory
        // Each thread loads one element of sA
        // The element is A[by * BLOCK_SIZE + ty][m * BLOCK_SIZE + tx]
        sA[ty][tx] = A[(by * BLOCK_SIZE + ty) * N + (m * BLOCK_SIZE + tx)];

        // Load B_tile from global memory to shared memory
        // Each thread loads one element of sB
        // The element is B[(m * BLOCK_SIZE + ty) * N + (bx * BLOCK_SIZE + tx)]
        sB[ty][tx] = B[(m * BLOCK_SIZE + ty) * N + (bx * BLOCK_SIZE + tx)];

        // Synchronize to make sure all data is loaded to shared memory
        __syncthreads();

        // Perform the dot product for the current tile
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            Pvalue += sA[ty][k] * sB[k][tx];
        }

        // Synchronize to make sure all threads in the block have finished computation
        __syncthreads();
    }

    // Write the result to global memory
    C[(by * BLOCK_SIZE + ty) * N + (bx * BLOCK_SIZE + tx)] = Pvalue;
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    // Get dimensions
    int N = A.size(0); // Assuming square matrix N x N

    // Allocate output tensor
    auto C = torch::zeros({N, N}, A.options());

    // Calculate grid and block dimensions
    dim3 block_dim(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid_dim((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    // Launch the kernel
    matmul_kernel<<<grid_dim, block_dim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code for matrix multiplication
matmul = load_inline(
    name="matmul_kernel",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul.matmul_cuda

    def forward(self, A, B):
        return self.matmul_cuda(A, B)
