#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32
#define TILE_SIZE BLOCK_SIZE
#define PAD_SIZE (BLOCK_SIZE + 1) // Padding to avoid bank conflicts

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // P_ij is the element of C that this thread will compute
    float Pvalue = 0;

    // Loop over the tiles of A and B that are needed to compute C_tile
    for (int m = 0; m < (N + TILE_SIZE - 1) / TILE_SIZE; ++m) {
        // Shared memory for A_tile and B_tile with padding for B
        __shared__ float sA[TILE_SIZE][TILE_SIZE];
        __shared__ float sB[TILE_SIZE][PAD_SIZE]; // Padded to avoid bank conflicts

        // Load A_tile from global memory to shared memory
        // Each thread loads one element of sA
        int a_row = by * TILE_SIZE + ty;
        int a_col = m * TILE_SIZE + tx;
        if (a_row < N && a_col < N) {
            sA[ty][tx] = A[a_row * N + a_col];
        } else {
            sA[ty][tx] = 0.0f; // Handle out-of-bounds access
        }

        // Load B_tile from global memory to shared memory
        // Each thread loads one element of sB
        int b_row = m * TILE_SIZE + ty;
        int b_col = bx * TILE_SIZE + tx;
        if (b_row < N && b_col < N) {
            sB[ty][tx] = B[b_row * N + b_col];
        } else {
            sB[ty][tx] = 0.0f; // Handle out-of-bounds access
        }

        // Synchronize to make sure all data is loaded to shared memory
        __syncthreads();

        // Perform the dot product for the current tile
        for (int k = 0; k < TILE_SIZE; ++k) {
            Pvalue += sA[ty][k] * sB[k][tx];
        }

        // Synchronize to make sure all threads in the block have finished computation
        __syncthreads();
    }

    // Write the result to global memory
    int c_row = by * TILE_SIZE + ty;
    int c_col = bx * TILE_SIZE + tx;
    if (c_row < N && c_col < N) {
        C[c_row * N + c_col] = Pvalue;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    // Get dimensions
    int N = A.size(0); // Assuming square matrix N x N

    // Allocate output tensor
    auto C = torch::zeros({N, N}, A.options());

    // Calculate grid and block dimensions
    dim3 block_dim(TILE_SIZE, TILE_SIZE);
    dim3 grid_dim((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch the kernel
    matmul_kernel<<<grid_dim, block_dim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

